<?php
require_once __DIR__ . '/../includes/auth.php'; require_login();
require_once __DIR__ . '/../includes/db.php'; require_once __DIR__ . '/../includes/admin_helpers.php';
$pageTitle='Customers | Restaurant Management';$error='';$edit=null;
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=mysqli_prepare($conn,"SELECT * FROM customers WHERE customer_id=?");mysqli_stmt_bind_param($s,"i",$id);mysqli_stmt_execute($s);$edit=mysqli_fetch_assoc(mysqli_stmt_get_result($s));mysqli_stmt_close($s);}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['customer_id']??0);$name=post_value('customer_name');$phone=post_value('phone');$email=post_value('email');if($name==='')$error='Customer name is required.';elseif($id){$s=mysqli_prepare($conn,"UPDATE customers SET customer_name=?,phone=?,email=? WHERE customer_id=?");mysqli_stmt_bind_param($s,"sssi",$name,$phone,$email,$id);if(mysqli_stmt_execute($s))admin_message('Customer updated.');else $error='Could not update customer.';mysqli_stmt_close($s);if(!$error)admin_redirect('customers.php');}else{$s=mysqli_prepare($conn,"INSERT INTO customers(customer_name,phone,email) VALUES(?,?,?)");mysqli_stmt_bind_param($s,"sss",$name,$phone,$email);if(mysqli_stmt_execute($s))admin_message('Customer added.');else $error='Could not add customer.';mysqli_stmt_close($s);if(!$error)admin_redirect('customers.php');}}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=mysqli_prepare($conn,"DELETE FROM customers WHERE customer_id=?");mysqli_stmt_bind_param($s,"i",$id);if(mysqli_stmt_execute($s))admin_message('Customer deleted.');else admin_message('Could not delete customer.','danger');mysqli_stmt_close($s);admin_redirect('customers.php');}
$list=mysqli_query($conn,"SELECT * FROM customers ORDER BY customer_id DESC");require_once __DIR__ . '/../includes/header.php';
?>
<h2>Customers</h2><p class="text-muted">Manage restaurant customers</p><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?>
<div class="card border-0 shadow-sm mb-4"><div class="card-header bg-white"><h5><?= $edit?'Edit Customer':'Add Customer' ?></h5></div><div class="card-body"><form method="POST" class="row g-3">
<input type="hidden" name="customer_id" value="<?=h($edit['customer_id']??0)?>"><div class="col-md-4"><label class="form-label">Customer Name</label><input class="form-control" name="customer_name" required value="<?=h($edit['customer_name']??'')?>"></div><div class="col-md-3"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=h($edit['phone']??'')?>"></div><div class="col-md-3"><label class="form-label">Email</label><input type="email" class="form-control" name="email" value="<?=h($edit['email']??'')?>"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary">Save</button> <a class="btn btn-secondary ms-2" href="customers.php">Clear</a></div></form></div></div>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th>Name</th><th>Phone</th><th>Email</th><th>Created</th><th>Action</th></tr></thead><tbody><?php if($list&&mysqli_num_rows($list)):while($r=mysqli_fetch_assoc($list)):?><tr><td><?=h($r['customer_name'])?></td><td><?=h($r['phone'])?></td><td><?=h($r['email'])?></td><td><?=h($r['created_at'])?></td><td><a class="btn btn-sm btn-warning" href="?edit=<?=$r['customer_id']?>">Edit</a> <a class="btn btn-sm btn-danger" onclick="return confirm('Delete customer?')" href="?delete=<?=$r['customer_id']?>">Delete</a></td></tr><?php endwhile;else:?><tr><td colspan="5" class="text-center p-3">No customers found.</td></tr><?php endif;?></tbody></table></div></div>
